// Pachinko pre-alert variants and per-digit slot presentation (v0.66.20).
const pachinkoHtmlBeforePreAlert = pachinkoHtml;
pachinkoHtml = function(p,i){
  let html=pachinkoHtmlBeforePreAlert(p,i);
  const alerts=Array.isArray(p.preAlerts)?p.preAlerts:[];
  const alertPanel=`<details data-p-section="preAlert" ${pachinkoSectionOpen(p,'preAlert')?'open':''}><summary>先バレ演出（最大3パターン）</summary><p class="note">当たり・CZ・STなどの条件に合った先バレから抽選します。各パターンで発生確率とタイミングを個別設定できます。テストボタンは条件・確率を無視して選んだ先バレを再生します。</p><div class="pPreAlertGrid">${[0,1,2].map(ix=>{const a=alerts[ix]||{};return `<details class="pPreAlert" data-index="${ix}" ${a.open?'open':''}><summary>先バレ ${ix+1}</summary><button class="secondary pPreTest" type="button">この先バレをテスト</button><label class="toggle"><input class="pPreEnabled" type="checkbox" ${a.enabled?'checked':''}>この先バレを使う</label><div class="cardSizeGrid"><div class="field"><label>発生条件</label><select class="pPreCondition"><option value="any" ${a.condition==='any'?'selected':''}>すべて</option><option value="hit" ${a.condition==='hit'?'selected':''}>大当たり</option><option value="miss" ${a.condition==='miss'?'selected':''}>はずれ</option><option value="cz-success" ${a.condition==='cz-success'?'selected':''}>CZ成功</option><option value="cz-fail" ${a.condition==='cz-fail'?'selected':''}>CZ失敗</option><option value="at" ${a.condition==='at'?'selected':''}>ST突入</option><option value="upper" ${a.condition==='upper'?'selected':''}>上位ST</option><option value="lt" ${a.condition==='lt'?'selected':''}>ラッキートリガー</option></select></div><div class="field"><label>発生確率（%）</label><input class="pPreChance" type="number" min="0" max="100" value="${a.chance??100}"></div><div class="field"><label>発生タイミング</label><select class="pPreTiming"><option value="spin-start" ${a.timing==='spin-start'?'selected':''}>回転開始前</option><option value="during-spin" ${a.timing==='during-spin'?'selected':''}>回転中（中間）</option><option value="before-result" ${!a.timing||a.timing==='before-result'?'selected':''}>結果表示の直前</option></select></div><div class="field"><label>表示タイプ</label><select class="pPreDisplay"><option value="full" ${a.displayMode!=='sound-only'&&a.displayMode!=='sound-text'?'selected':''}>演出素材＋音＋テキスト</option><option value="sound-only" ${a.displayMode==='sound-only'?'selected':''}>音のみ（回転演出を維持）</option><option value="sound-text" ${a.displayMode==='sound-text'?'selected':''}>音＋テキスト</option></select></div></div><div class="field"><label class="toggle"><input class="pPreShowText" type="checkbox" ${a.showText!==false?'checked':''}>先バレテキストを表示</label><div class="cardSizeGrid"><input class="pPreText" type="text" maxlength="80" value="${escapeRoleValue(a.text||'チャンス！')}" aria-label="先バレ表示テキスト"><input class="pPreColor" type="color" value="${a.color||'#ffe05b'}" aria-label="先バレ文字色"><input class="pPreTextSize" type="number" min="14" max="300" value="${a.textSize??56}" aria-label="先バレ文字サイズ"><input class="pPreTextSeconds" type="number" min="0.2" max="120" step="0.1" value="${a.textSeconds??1.2}" aria-label="テキスト表示秒数"></div><small class="note">テキスト／色／サイズ／表示秒数</small></div><div class="cardSizeGrid"><div class="field"><label>画像・動画（30MB以下）</label><input class="pPreMedia" data-kind="animation" type="file" accept="image/*,video/mp4,video/webm"><span class="note">${p['preAlert'+(ix+1)+'AnimationName']||'未設定'}</span><button class="secondary pPreClearMedia" data-kind="animation" type="button">素材解除</button></div><div class="field"><label>専用音源（15MB以下）</label><input class="pPreMedia" data-kind="audio" type="file" accept="audio/*"><span class="note">${p['preAlert'+(ix+1)+'AudioName']||'未設定'}</span><button class="secondary pPreClearMedia" data-kind="audio" type="button">素材解除</button></div><div class="field"><label>素材の表示時間（秒）</label><input class="pPreMediaSeconds" type="number" min="0" max="120" step="0.1" value="${a.mediaSeconds??0}"><small>0ならテキスト／音源の設定時間を使用</small></div><div class="field"><label>音源の再生時間（秒、0なら指定なし）</label><input class="pPreAudioSeconds" type="number" min="0" max="120" step="0.1" value="${a.audioSeconds??0}"></div><div class="field"><label>音源音量（%）</label><input class="pPreAudioVolume" type="number" min="0" max="100" value="${a.audioVolume??75}"></div><div class="field"><label>動画音量（%）</label><input class="pPreVideoVolume" type="number" min="0" max="100" value="${a.videoVolume??75}"></div></div></details>`}).join('')}</div></details>`;
  const digitRows=(p.digitSettings||Array.from({length:10},(_,d)=>({text:String(d),fontFamily:'global',color:'#ffffff',size:130,imageUrl:'',imageName:'',imageSize:130}))).map((d,ix)=>`<div class="pDigitRow" data-digit="${ix}"><strong>${ix} の表示</strong><input class="pDigitText" maxlength="8" value="${escapeRoleValue(d.text??String(ix))}" aria-label="${ix}の表示文字"><select class="pDigitFont" aria-label="${ix}のフォント"><option value="global" ${d.fontFamily==='global'?'selected':''}>共通</option><option value="system" ${d.fontFamily==='system'?'selected':''}>標準</option><option value="yuGothic" ${d.fontFamily==='yuGothic'?'selected':''}>游ゴシック</option><option value="meiryo" ${d.fontFamily==='meiryo'?'selected':''}>メイリオ</option><option value="gothic" ${d.fontFamily==='gothic'?'selected':''}>太字ゴシック</option><option value="serif" ${d.fontFamily==='serif'?'selected':''}>明朝</option><option value="mono" ${d.fontFamily==='mono'?'selected':''}>等幅</option></select><input class="pDigitColor" type="color" value="${d.color||'#ffffff'}" aria-label="${ix}の文字色"><label class="pDigitSizeField"><small>文字サイズ (px)</small><input class="pDigitSize" type="number" min="14" max="400" value="${d.size??130}" aria-label="${ix}の文字サイズ"></label><label class="pDigitSizeField"><small>画像サイズ (px)</small><input class="pDigitImageSize" type="number" min="20" max="1200" value="${d.imageSize??130}" aria-label="${ix}の画像サイズ"></label><input class="pDigitImage" type="file" accept="image/*" aria-label="${ix}の画像"><span class="note">${d.imageName||'画像なし'}</span><button class="secondary pDigitClear" type="button">画像解除</button></div>`).join('');
  const digitPanel=`<details data-p-section="digits" ${pachinkoSectionOpen(p,'digits')?'open':''}><summary>回転中の数字（0〜9）個別設定</summary><p class="note">回転中に流れる3桁の数字を、数字ごとに文字・フォント・色・サイズ・画像へ変更できます。画像を設定した数字は文字の代わりに表示します。</p><div class="pDigitGrid">${digitRows}</div></details>`;
  const insert=html.indexOf('<details class="textRoleEditor');
  return insert>=0?html.slice(0,insert)+alertPanel+digitPanel+html.slice(insert):html.replace('</article>',alertPanel+digitPanel+'</article>');
};

