bindPachinko=function(el,i){bindPachinkoBeforePreAlertUI(el,i);const pattern=state.pachinkoGacha.patterns[i];el.querySelectorAll('.pPreTest').forEach(button=>button.onclick=async()=>{try{collectPachinko();await persist();const preAlertIndex=Number(button.closest('.pPreAlert').dataset.index);await postJson('/api/pachinko/test',{patternId:pattern.id,preAlertIndex});setStatus(`先バレ ${preAlertIndex+1} のテストを開始しました（条件・確率は無視します）`)}catch(e){setStatus('先バレをテストできませんでした：'+e.message)}});el.querySelectorAll('.pPreMedia').forEach(input=>input.onchange=()=>uploadPachinkoPreAlert(pattern,+input.closest('.pPreAlert').dataset.index,input.dataset.kind,input.files[0]));el.querySelectorAll('.pPreClearMedia').forEach(btn=>btn.onclick=()=>uploadPachinkoPreAlert(pattern,+btn.closest('.pPreAlert').dataset.index,btn.dataset.kind,null,true));el.querySelectorAll('.pDigitImage').forEach(input=>input.onchange=()=>uploadPachinkoDigitImage(pattern,+input.closest('.pDigitRow').dataset.digit,input.files[0]));el.querySelectorAll('.pDigitClear').forEach(btn=>btn.onclick=()=>uploadPachinkoDigitImage(pattern,+btn.closest('.pDigitRow').dataset.digit,null,true));const beepFile=el.querySelector('.pBeepFile'),beepName=el.querySelector('.pBeepName');beepFile.onchange=()=>uploadPachinkoMedia(pattern,'spinBeep','audio',beepFile.files[0]);el.querySelector('.pBeepClear').onclick=()=>uploadPachinkoMedia(pattern,'spinBeep','audio',null,true);el.querySelector('.pBeepTest').onclick=()=>{collectPachinko();playPachinkoBeep(state.pachinkoGacha.patterns[i]);};el.querySelectorAll('.pPreAlert input:not([type=file]),.pPreAlert select,.pDigitRow input:not([type=file]),.pDigitRow select').forEach(input=>input.addEventListener(input.type==='checkbox'||input.tagName==='SELECT'?'change':'input',()=>{collectPachinko();save()}))};
async function uploadPachinkoPreAlert(pattern,index,kind,file,clear=false){if(file&&file.size>(kind==='audio'?15:30)*1024*1024){setStatus((kind==='audio'?'音源':'画像・動画')+'は上限サイズ以下にしてください');return}try{collectPachinko();await persist();const stage='preAlert'+(index+1),d=await postJson('/api/pachinko/media',{patternId:pattern.id,stage,kind,clear,...(file?{name:file.name,dataUrl:await readFile(file)}:{})});state.pachinkoGacha=d.pachinkoGacha;Object.assign(pattern,state.pachinkoGacha.patterns.find(x=>x.id===pattern.id)||{});const box=document.querySelector(`.pachinkoPattern[data-id="${pattern.id}"] .pPreAlert[data-index="${index}"]`);if(box){const name=kind==='audio'?pattern[stage+'AudioName']:pattern[stage+'AnimationName'];const span=box.querySelector(`.pPreMedia[data-kind="${kind}"]`)?.nextElementSibling;if(span)span.textContent=name||'未設定';const input=box.querySelector(`.pPreMedia[data-kind="${kind}"]`);if(input)input.value=''}save();setStatus(clear?'先バレ素材を解除しました':'先バレ素材を保存しました')}catch(e){setStatus('先バレ素材を変更できませんでした：'+e.message)}}
async function uploadPachinkoDigitImage(pattern,digit,file,clear=false){if(file&&file.size>15*1024*1024){setStatus('数字画像は15MB以下にしてください');return}try{collectPachinko();await persist();const d=await postJson('/api/pachinko/digit-image',{patternId:pattern.id,digit,clear,...(file?{name:file.name,dataUrl:await readFile(file)}:{})});state.pachinkoGacha=d.pachinkoGacha;Object.assign(pattern,state.pachinkoGacha.patterns.find(x=>x.id===pattern.id)||{});const row=document.querySelector(`.pachinkoPattern[data-id="${pattern.id}"] .pDigitRow[data-digit="${digit}"]`);if(row){row.querySelector('.note').textContent=pattern.digitSettings?.[digit]?.imageName||'画像なし';row.querySelector('.pDigitImage').value=''}save();setStatus(clear?'数字画像を解除しました':'数字画像を保存しました')}catch(e){setStatus('数字画像を変更できませんでした：'+e.message)}}
const pachinkoPreAlertStyle=document.createElement('style');pachinkoPreAlertStyle.textContent='.pPreAlertGrid{display:grid;gap:12px}.pPreAlert{padding:10px;border:1px solid #55476f;border-radius:10px;background:#12101a}.pDigitGrid{display:grid;gap:8px}.pDigitRow{display:grid;grid-template-columns:90px minmax(90px,1fr) minmax(115px,1fr) 60px 105px 105px minmax(120px,1fr) minmax(80px,1fr) auto;gap:7px;align-items:center;padding:8px;border:1px solid #3c3e49;border-radius:8px}.pDigitRow strong{color:#ffd26b}.pDigitRow input,.pDigitRow select{min-width:0;width:100%}.pDigitSizeField{display:grid;gap:3px;min-width:0}.pDigitSizeField small{font-size:11px;color:#c8c5d1;white-space:nowrap}.pDigitSizeField input{box-sizing:border-box}@media(max-width:950px){.pDigitRow{grid-template-columns:repeat(3,minmax(0,1fr))}.pDigitRow strong{grid-column:1/-1}}';document.head.append(pachinkoPreAlertStyle);
